SELECT review_id, member_id, product_id, rating, title, body,
       is_published, is_blocked, created_at, updated_at
FROM reviews
WHERE member_id = #{memberId}
  AND product_id = #{productId}

SELECT EXISTS (
    SELECT 1
    FROM orders o
    JOIN order_items oi ON oi.order_id = o.order_id
    JOIN product_variants pv ON pv.product_code = oi.product_code
    WHERE o.member_id = #{memberId}
      AND o.order_status != 'cancelled'
      AND pv.product_id = #{productId}
)

SELECT product_id, COUNT(*) AS review_count, AVG(rating) AS average_rating FROM reviews WHERE is_published = TRUE AND product_id IN
#{productId}
GROUP BY product_id
